mapper.insert:
 		insert into tbl_rental (
			con_serial
			, ttl_serial
			, mb_id
			, rt_days
			, rt_shipfee
			, rt_quantities
			, rt_amount
			, rt_regdate
			, rt_payment
			, rt_state
			, rt_name
			, rt_zipcode
			, rt_addr
			, rt_addrdet
			, rt_tel
			, rt_req
			, rt_startdate
			, rt_enddate
			, rt_rtndate
			, rt_moddate
 		) values (
			#{con_serial}
			, #{ttl_serial}
			, #{mb_id}
			, #{rt_days}
			, #{rt_shipfee}
			, #{rt_quantities}
			, #{rt_amount}
			, now()
			, #{rt_payment}
			, 0
			, #{rt_name}
			, #{rt_zipcode}
			, #{rt_addr}
			, #{rt_addrdet}
			, #{rt_tel}
			, #{rt_req}
			, #{rt_startdate}
			, DATE_ADD(#{rt_startdate}, INTERVAL #{rt_days} DAY)
			, null
			, now()
 		)
